function find(query) {
    var words = query.toLocaleLowerCase().trim().split(/\s+/);
    if (!query.trim()) return [];
    var result = [];
    for (var i = 0; i < entries.length; ++i) {
        var e = entries[i], translated = qsTranslate("SettingsTab" + e[0], e[1]);
        var haystack = (translated + " " + e[1]).toLocaleLowerCase();
        if (words.every(function(word) { return haystack.indexOf(word) >= 0; }))
            result.push({tab:e[0], label:translated});
        if (result.length >= 80) break;
    }
    return result;
}
